const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),pct=v=>Number.isFinite(v)?(v*100).toFixed(2)+'%':'—';
const labels={PREPARING:'학습 준비',COLLECTING:'최근 자료 수집',TRAINING:'후보 학습',WAITING_START:'모의 비교 시작 대기',COMPARING:'기존 모델과 모의 비교',APPLYING:'검증된 가중치 반영 중',IDLE:'다음 학습 대기',PAUSED:'자동 학습 꺼짐',RETRY_WAIT:'연결 복구 대기'};
export function renderHourlyLearning(item,{detailsOpen=false,pending=null,error=''}={}){
 if(!item)return '';
 const t=item.trial,c=t?.comparison,m=t?.status==='WAITING_START'?null:c?.metrics,local=v=>v?new Date(v).toLocaleString('ko-KR'):'—',state=!item.enabled?'PAUSED':t?.status==='WAITING_START'?'WAITING_START':item.status;
 return '<section class="studio-sheet spaced" data-hourly-learning><div class="studio-sheet-body"><div class="panel-head"><div><div class="badge-row"><h2>자동 학습</h2><span class="pill" role="status">'+esc(labels[state]??state)+'</span></div><p>'+(!item.enabled?'다시 켜면 ':'')+(item.autoApply?'비교 통과 시 가중치 자동 갱신':'후보 비교만 수행')+'</p></div><button type="button" class="button" data-auto-action="learning-toggle" data-learning-enabled="'+String(!item.enabled)+'"'+(pending?' disabled aria-busy="true"':'')+'>'+(pending?(pending.enabled?'자동 학습 켜는 중…':'자동 학습 끄는 중…'):item.enabled?'자동 학습 끄기':'자동 학습 켜기')+'</button></div>'+(error?'<p class="error-text" role="alert">'+esc(error)+'</p>':'')+'<p>최근 7일 학습 → 기존 모델·새 후보·BTC를 24시간 모의 비교 → 통과한 가중치 반영</p><p>배정액·주문 한도·분할익절 규칙은 유지됩니다.</p>'+(item.training?'<p>최근 학습 '+esc(local(item.training.at))+' · '+esc(item.training.sampleCount)+'개 표본</p>':'')+(t?'<p>비교 '+esc(local(t.startsAt))+' ~ '+esc(local(t.endsAt))+'</p>':'')+(m?'<div class="table-scroll"><table class="table"><thead><tr><th>비교 대상</th><th>비용 차감 수익률</th><th>관측 낙폭</th></tr></thead><tbody>'+[['baseline','기존 모델'],['candidate','새 후보'],['btc','BTC 보유']].map(([k,n])=>'<tr><td>'+n+'</td><td>'+pct(m[k]?.netReturn)+'</td><td>'+pct(m[k]?.mdd)+'</td></tr>').join('')+'<tr><td>현금</td><td>0%</td><td>0%</td></tr></tbody></table></div>':'')+(item.scores?'<p>6시간 후 채점 완료 '+esc(item.scores.forecastHours)+'개 시점 · 최근 평균 예측 오차 '+pct(item.scores.last24hMae)+'</p>':'')+(item.lastApplied?'<p>최근 자동 반영 '+esc(local(item.lastApplied.at))+'</p>':'')+(item.lastError?'<p class="error-text" role="alert">'+(!item.enabled?'중지 전 학습 오류 · ':state==='RETRY_WAIT'?'연결 복구 대기 · ':'최근 학습 오류 · ')+''+esc(item.lastError.code)+'</p>':'')+'<details'+(detailsOpen?' open':'')+'><summary data-auto-action="learning-details">자동 갱신 기준과 자료 조회</summary><p>후보가 비용 차감 후 양의 수익을 내고, 기존 모델보다 수익률이 높고 MDD가 같거나 작으며, 완결 거래와 평가 경로를 확보하면 자동 반영합니다. 회복 기간·BTC 대비 성과도 함께 보존합니다.</p><p>정시 판단·진입가격 재평가·100ms 주문 준비·관측 호가·FOK·20bps 가격캡을 같은 경로로 비교합니다.</p><p>매일 조회 한도 '+esc(item.maxRequestsPerDay)+'회 · 사용 '+esc(item.requests?.used??0)+'회</p></details></div></section>';
}
